package noresponse

// Auth context adapters. Generated by tools/generate_auth_adapters.py; do not edit.
//
// Each adapter maps claims your backend has already verified into the
// auth_context of an assessment request. Pass verified claims, not a raw token.
//
// The mapping is the claim map (contracts/api/v1/fixtures/assessment-contract/
// auth-context-claim-map.json), run by the small interpreter below. Every SDK
// runs the same table and the same vectors. A claim that is missing, mistyped
// or out of range maps to absent, never to a stronger assurance.

import (
	"encoding/json"
	"errors"
	"math"
	"regexp"
	"strings"
	"time"
	"unicode/utf8"

	"github.com/noresponsehq/go/v2/models/components"
)

// ErrInvalidAuthContext is returned when the claims have no valid issuer and
// subject, or the provider is not a lowercase slug.
var ErrInvalidAuthContext = errors.New("noresponse: invalid auth context")

const authClaimMapJSON = `{"version":1,"kinds":{"id":{"pattern":"[A-Za-z0-9._:@/|+=~-]+","maxLength":256},"audience":{"pattern":"[A-Za-z0-9._:/-]+","maxLength":256},"role":{"pattern":"[A-Za-z0-9._:@/-]+","maxLength":64},"method":{"pattern":"[A-Za-z0-9._:-]+","maxLength":32},"issuer":{"pattern":"https://[\\x21-\\x7e]+","maxLength":256},"time":{"pattern":"[0-9]{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:([0-5][0-9]|60)(\\.[0-9]+)?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])","maxLength":64}},"slug":"[a-z0-9][a-z0-9._-]{1,31}","constants":{"verified":true,"transport":"backend"},"base":{"issuer":{"op":"id","kind":"issuer","claims":["iss"],"required":true},"subject":{"op":"id","kind":"id","claims":["sub"],"required":true},"audiences":{"op":"list","kind":"audience","claims":["aud"],"split":"whitespace","max":8},"issued_at":{"op":"time","claims":["iat"]},"expires_at":{"op":"time","claims":["exp"]},"auth_time":{"op":"time","claims":["auth_time"]},"session_id":{"op":"id","kind":"id","claims":["sid"]},"token_id":{"op":"id","kind":"id","claims":["jti"]}},"providers":{"workos":{"fields":{"organization_id":{"op":"id","kind":"id","claims":["org_id"]},"roles":{"op":"list","kind":"role","claims":["roles","role"],"split":"whitespace","max":32},"scopes":{"op":"list","kind":"role","claims":["permissions"],"split":"whitespace","max":32},"impersonated":{"op":"actor","claims":["act"]}}},"clerk":{"disable":["issued_at"],"fields":{"organization_id":{"op":"id","kind":"id","claims":["o.id","org_id"]},"roles":{"op":"list","kind":"role","claims":["o.rol","org_role"],"split":"none","max":32},"scopes":{"op":"list","kind":"role","claims":["o.per","org_permissions"],"split":"comma_whitespace","max":32},"impersonated":{"op":"actor","claims":["act"]},"mfa":{"op":"mfa_factor_age","claim":"fva","index":1,"unitSeconds":60,"maxSeconds":315360000}}},"auth0":{"fields":{"organization_id":{"op":"id","kind":"id","claims":["org_id"]},"scopes":{"op":"list","kind":"role","claims":["scope","permissions"],"split":"whitespace","max":32},"email_verified":{"op":"bool","claims":["email_verified"]},"phone_verified":{"op":"bool","claims":["phone_number_verified"]},"impersonated":{"op":"actor","claims":["act"]},"mfa":{"op":"mfa_methods","kind":"method","claim":"amr","max":8,"mfaValue":"mfa","ignore":["pwd"]}}},"oidc":{"slugArgument":true,"fields":{}}}}`

type authRule struct {
	Op          string   `json:"op"`
	Kind        string   `json:"kind"`
	Claims      []string `json:"claims"`
	Claim       string   `json:"claim"`
	Split       string   `json:"split"`
	Max         int      `json:"max"`
	Index       int      `json:"index"`
	UnitSeconds float64  `json:"unitSeconds"`
	MaxSeconds  float64  `json:"maxSeconds"`
	MFAValue    string   `json:"mfaValue"`
	Ignore      []string `json:"ignore"`
}

type authKind struct {
	Pattern   string `json:"pattern"`
	MaxLength int    `json:"maxLength"`
	re        *regexp.Regexp
}

type authProvider struct {
	Disable []string            `json:"disable"`
	Fields  map[string]authRule `json:"fields"`
}

type authClaimMap struct {
	Kinds     map[string]*authKind    `json:"kinds"`
	Slug      string                  `json:"slug"`
	Constants map[string]any          `json:"constants"`
	Base      map[string]authRule     `json:"base"`
	Providers map[string]authProvider `json:"providers"`
}

var (
	authMap  = loadAuthClaimMap()
	authSlug = regexp.MustCompile("^(?:" + authMap.Slug + ")$")
	// Space, tab, CR, LF, FF and VT; the claim map's `whitespace` split.
	authSplitters = map[string]*regexp.Regexp{
		"whitespace":       regexp.MustCompile(`[ \t\r\n\f\v]+`),
		"comma_whitespace": regexp.MustCompile(`[ \t\r\n\f\v,]+`),
	}
)

const authMaxTime = 253402300799

func loadAuthClaimMap() *authClaimMap {
	var m authClaimMap
	if err := json.Unmarshal([]byte(authClaimMapJSON), &m); err != nil {
		panic("noresponse: bad embedded claim map: " + err.Error())
	}
	for _, kind := range m.Kinds {
		kind.re = regexp.MustCompile("^(?:" + kind.Pattern + ")$")
	}
	return &m
}

func authLookup(claims map[string]any, path string) any {
	var current any = claims
	for _, key := range strings.Split(path, ".") {
		object, ok := current.(map[string]any)
		if !ok {
			return nil
		}
		if current, ok = object[key]; !ok {
			return nil
		}
	}
	return current
}

func authMatches(kind string, value any) (string, bool) {
	text, ok := value.(string)
	if !ok {
		return "", false
	}
	k := authMap.Kinds[kind]
	if utf8.RuneCountInString(text) > k.MaxLength || !k.re.MatchString(text) {
		return "", false
	}
	return text, true
}

func authLower(value string) string {
	return strings.Map(func(r rune) rune {
		if r >= 'A' && r <= 'Z' {
			return r + 32
		}
		return r
	}, value)
}

func authContains(values []string, value string) bool {
	for _, item := range values {
		if item == value {
			return true
		}
	}
	return false
}

func authMapRule(claims map[string]any, rule authRule) any {
	switch rule.Op {
	case "id":
		for _, path := range rule.Claims {
			if text, ok := authMatches(rule.Kind, authLookup(claims, path)); ok {
				return text
			}
		}
	case "list":
		for _, path := range rule.Claims {
			var items []any
			switch value := authLookup(claims, path).(type) {
			case string:
				if rule.Split == "none" {
					items = []any{value}
				} else {
					for _, piece := range authSplitters[rule.Split].Split(value, -1) {
						items = append(items, piece)
					}
				}
			case []any:
				items = value
			}
			kept := []string{}
			for _, item := range items {
				if text, ok := authMatches(rule.Kind, item); ok && len(kept) < rule.Max {
					kept = append(kept, text)
				}
			}
			if len(kept) > 0 {
				return kept
			}
		}
	case "time":
		for _, path := range rule.Claims {
			value := authLookup(claims, path)
			if number, ok := value.(float64); ok && number >= 0 && number <= authMaxTime {
				// Whole UTC seconds; the fraction is truncated.
				return time.Unix(int64(number), 0).UTC().Format("2006-01-02T15:04:05Z")
			}
			if text, ok := authMatches("time", value); ok {
				return text
			}
		}
	case "bool":
		for _, path := range rule.Claims {
			if value, ok := authLookup(claims, path).(bool); ok {
				return value
			}
		}
	case "actor":
		switch value := authLookup(claims, rule.Claims[0]).(type) {
		case map[string]any:
			for _, key := range []string{"sub", "email"} {
				if text, ok := value[key].(string); ok && text != "" {
					return true
				}
			}
			return false
		case string:
			return value != ""
		}
		return false
	case "mfa_factor_age":
		list, _ := authLookup(claims, rule.Claim).([]any)
		if len(list) <= rule.Index {
			return nil
		}
		age, ok := list[rule.Index].(float64)
		if !ok {
			return nil
		}
		seconds := age * rule.UnitSeconds
		if math.IsNaN(seconds) || seconds < 0 || seconds > rule.MaxSeconds {
			return nil
		}
		return map[string]any{"present": true, "age_seconds": int64(seconds)}
	case "mfa_methods":
		list, _ := authLookup(claims, rule.Claim).([]any)
		kept := []string{}
		for _, item := range list {
			if text, ok := authMatches(rule.Kind, item); ok && len(kept) < rule.Max {
				kept = append(kept, text)
			}
		}
		methods := []string{}
		present := false
		for _, item := range kept {
			if authLower(item) == rule.MFAValue {
				present = true
			}
			if !authContains(rule.Ignore, authLower(item)) {
				methods = append(methods, item)
			}
		}
		if len(methods) == 0 {
			return nil
		}
		return map[string]any{"present": present, "methods": methods}
	default:
		panic("noresponse: unknown claim map op " + rule.Op)
	}
	return nil
}

// authNormalise turns any JSON-shaped value (map, struct, json.RawMessage)
// into plain maps, slices, strings, float64 and bool.
func authNormalise(value any) (map[string]any, error) {
	raw, err := json.Marshal(value)
	if err != nil {
		return nil, err
	}
	var out map[string]any
	if err := json.Unmarshal(raw, &out); err != nil {
		return nil, err
	}
	return out, nil
}

func authBuild(name, provider string, rawClaims, rawOverrides map[string]any) (*components.AuthContext, error) {
	claims, err := authNormalise(rawClaims)
	if err != nil {
		return nil, errors.Join(ErrInvalidAuthContext, err)
	}
	overrides, err := authNormalise(rawOverrides)
	if err != nil {
		return nil, errors.Join(ErrInvalidAuthContext, err)
	}
	spec := authMap.Providers[name]
	rules := map[string]authRule{}
	for field, rule := range authMap.Base {
		rules[field] = rule
	}
	for field, rule := range spec.Fields {
		rules[field] = rule
	}
	for _, field := range spec.Disable {
		delete(rules, field)
	}
	wire := map[string]any{"provider": provider}
	for key, value := range authMap.Constants {
		wire[key] = value
	}
	for field, rule := range rules {
		if value := authMapRule(claims, rule); value != nil {
			wire[field] = value
		}
	}
	for field, value := range overrides {
		if value != nil {
			wire[field] = value
		}
	}
	if audiences, ok := wire["audiences"].([]string); ok && len(audiences) > 0 {
		if _, set := wire["audience"]; !set {
			wire["audience"] = audiences[0]
		}
	}
	if audiences, ok := wire["audiences"].([]any); ok && len(audiences) > 0 {
		if _, set := wire["audience"]; !set {
			wire["audience"] = audiences[0]
		}
	}
	for _, key := range []string{"issuer", "subject"} {
		if text, _ := wire[key].(string); text == "" {
			return nil, errors.Join(ErrInvalidAuthContext, errors.New("a verified issuer and subject are required"))
		}
	}
	encoded, err := json.Marshal(wire)
	if err != nil {
		return nil, errors.Join(ErrInvalidAuthContext, err)
	}
	var context components.AuthContext
	if err := json.Unmarshal(encoded, &context); err != nil {
		return nil, errors.Join(ErrInvalidAuthContext, err)
	}
	return &context, nil
}

// FromWorkOSClaims maps verified WorkOS AuthKit claims plus verified user or
// session record overrides. Overrides use the auth_context field names, for
// example "email_verified".
func FromWorkOSClaims(claims, overrides map[string]any) (*components.AuthContext, error) {
	return authBuild("workos", "workos", claims, overrides)
}

// FromClerkClaims maps verified Clerk session claims. Pass Session.createdAt as
// the "session_created_at" override.
func FromClerkClaims(claims, overrides map[string]any) (*components.AuthContext, error) {
	return authBuild("clerk", "clerk", claims, overrides)
}

// FromAuth0Claims maps verified Auth0 ID token, userinfo or normalised session
// claims. Do not pass an opaque API access token.
func FromAuth0Claims(claims, overrides map[string]any) (*components.AuthContext, error) {
	return authBuild("auth0", "auth0", claims, overrides)
}

// FromOIDCClaims is the generic adapter for providers without a first-class
// helper. provider is a lowercase slug.
func FromOIDCClaims(provider string, claims, overrides map[string]any) (*components.AuthContext, error) {
	if !authSlug.MatchString(provider) {
		return nil, errors.Join(ErrInvalidAuthContext, errors.New("provider must be a lowercase provider slug"))
	}
	return authBuild("oidc", provider, claims, overrides)
}
